 const two=new OutbreakRules([0,1],0,{announcementTicks:1,countdownTicks:1,graceTicks:60});two.advanceClock(2);m.reset();assert.deepEqual(m.update(two.view(2),1).map(e=>e.cue),['go','last']);for(let round=0;round<2;round++){two.infect(round?6:3,[[0,1]]);m.update(two.view(round?6:3),1);two.next(round?7:4);if(!round)two.advanceClock(6);}assert.equal(two.view(7).matchWinners.length,2);assert.deepEqual(m.update(two.view(7),1).map(e=>e.cue),['win']);assert.deepEqual(m.update(two.view(8),1),[]);m.update(undefined,1);assert.deepEqual(m.update(new OutbreakRules([0,1],0).view(0),1).map(e=>e.cue),['reveal']);
});
