test('Chaos leads shared rules, with accurate voting/KEEP rules and three equally structured game-mode descriptions',()=>{const start=html.indexOf('id="guide-content"'),guide=html.slice(start,html.indexOf('id="help-live-note"',start));assert.ok(guide.indexOf('Chaos Voting')<guide.indexOf('Move. Jump. Tongue.'));for(const text of['20 wild modifiers','Round 1 is normal','15 seconds','Up to 3 effects stack','KEEP','host can turn it off'])assert.ok(guide.includes(text),text);for(const mode of['Poison Tag','Freeze Tag','Classic Tag'])assert.equal((guide.match(new RegExp('<summary>'+mode+' rules</summary>','g'))??[]).length,1);assert.equal((guide.match(/data-guide-mode=/g)??[]).length,3);assert.ok(guide.includes('Same-time last survivors share the bonus'));assert.ok(guide.includes('No automatic thaw'));assert.ok(guide.includes('New IT cannot tag for 1 second'));assert.ok(guide.includes('guide-desktop')&&guide.includes('guide-touch'));assert.ok(guide.includes('Left pad:')&&guide.includes('charged jump'));});
test('single persistent help opens in home/lobby and remains reachable through game menu with safe input clearing',()=>{const old=(globalThis as any).document,elements=new Map<string,any>();const element=(id:string):any=>{if(elements.has(id))return elements.get(id);const e={open:false,textContent:'',onclick:undefined as any,parentElement:null as any,showModal(){this.open=true;},close(){this.open=false;},append(child:any){child.parentElement=this;},addEventListener(){}};elements.set(id,e);return e;};(globalThis as any).document={getElementById:element,querySelector:element,activeElement:{blur(){}},addEventListener(){}};let cleared=0;try{const guide=new PlayerGuide(()=>cleared++);for(const phase of['home','lobby']){guide.update(phase,false);element('help').onclick();assert.ok(element('help-dialog').open);element('help-close').onclick();assert.ok(!guide.blocking);}guide.update('game',true);element('help').onclick();assert.ok(element('game-menu').open);element('menu-help').onclick();assert.ok(!element('game-menu').open&&element('help-dialog').open);element('help-close').onclick();assert.ok(!guide.blocking);assert.equal(cleared,8);}finally{(globalThis as any).document=old;}});
test('rules-only changes preserve all CPU, physics, modifiers, arenas, networking, cosmetics and iPhone sources exactly',()=>{const m=JSON.parse(readFileSync('docs/rules-guide-preservation.json','utf8')),hash=(s:any)=>createHash('sha256').update(s).digest('hex');for(const[p,h]of Object.entries(m.protected))assert.equal(hash(readFileSync(p)),h,p);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(readFileSync(p)),r.afterSha256,p);}assert.ok(html.includes('width=device-width,initial-scale=1,viewport-fit=cover'));assert.ok(!html.includes('user-scalable=no'));});
